 public static void Open(IWin32Window owner){var open=Application.OpenForms.OfType<DossierProjectManager>().FirstOrDefault();if(open==null)StudioModule.ShowDocument(new DossierProjectManager(),owner);else{open.WindowState=FormWindowState.Normal;StudioModule.ActivateDocument(open);}}
