  var tools=new FlowLayoutPanel{Dock=DockStyle.Fill,WrapContents=true};Button(tools,"New project",NewProject);Button(tools,"Open project",OpenPicker);Button(tools,"Project ideas",OpenIdeas);Button(tools,"Open decks",()=>StudioModule.ShowDocument(new DossierDeckForm(),this));Button(tools,"Refresh files",RefreshFiles);Button(tools,"Open folder",()=>Reveal(false));Button(tools,"Help",()=>DossierHelp.Open(this));root.Controls.Add(tools,0,0);
