  var details=Grid(1,8);details.Padding=new Padding(12);foreach(var h in new[]{26,36,54,60,28})details.RowStyles.Add(new RowStyle(SizeType.Absolute,h));details.RowStyles.Add(new RowStyle(SizeType.Percent,100));details.RowStyles.Add(new RowStyle(SizeType.Absolute,44));details.RowStyles.Add(new RowStyle(SizeType.Absolute,70));details.Controls.Add(new Label{Text="Project name",Dock=DockStyle.Fill},0,0);details.Controls.Add(name,0,1);details.Controls.Add(location,0,2);details.Controls.Add(summary,0,3);details.Controls.Add(new Label{Text="Description / project notes",Dock=DockStyle.Fill},0,4);details.Controls.Add(description,0,5);var save=new DossierButton{Text="Save project details",Dock=DockStyle.Fill};save.Click+=(_,__)=>Run(SaveDetails);details.Controls.Add(save,0,6);details.Controls.Add(new Label{Text="Entries keep their own embedded Notes. Project ideas have a separate board saved in this project folder.",Dock=DockStyle.Fill},0,7);overviewGrid.Controls.Add(details,0,0);
