 static TableLayoutPanel Grid(int columns,int rows){var grid=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=columns,RowCount=rows};for(int i=0;i<columns;i++)grid.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100f/columns));return grid;}
 void Button(FlowLayoutPanel parent,string text,Action action){var b=new DossierButton{Text=text,Width=122,Height=32};b.Click+=(_,__)=>Run(action);parent.Controls.Add(b);}
 void Run(Action action){try{action();}catch(Exception ex){status.Text=ex.Message;}}
 void RequireProject(){if(project==null)throw new InvalidOperationException("Create or open a project first.");}
 bool DirtyDetails()=>project!=null&&(name.Text!=project.Name||description.Text!=(project.Description??""));
 bool LeaveDetails(){if(!DirtyDetails())return true;var choice=DossierDialog.Show(this,"Save the project name and description before continuing?","Project details",MessageBoxButtons.YesNoCancel);if(choice==DialogResult.Cancel)return false;if(choice==DialogResult.No)return true;try{SaveDetails();return true;}catch(Exception ex){status.Text=ex.Message;return false;}}
 void NewProject(){if(!LeaveDetails())return;using(var dialog=new DossierFolderBrowserDialog{Description="Choose a project home. Standard entry and asset subfolders will be created here.",ShowNewFolderButton=true})if(dialog.ShowDialog(this)==DialogResult.OK){project=DossierProject.Create(dialog.SelectedPath);Remember();Render();status.Text="Project created. Add files, link folders or open Project ideas to start planning.";}}
 void OpenPicker(){using(var dialog=new DossierOpenFileDialog{Title="Open Dossier project",Filter="Dossier project (dossier-project.json)|dossier-project.json|JSON (*.json)|*.json"})if(dialog.ShowDialog(this)==DialogResult.OK)LoadProject(dialog.FileName);}
 public void LoadProject(string path){if(!LeaveDetails())return;var loaded=DossierProject.Load(path);project=loaded;Remember();Render();status.Text="Opened "+project.Name;}
 void Remember(){var prefs=DossierPreferences.Current;prefs.RecentProjects.RemoveAll(p=>string.Equals(p,project.ManifestPath,StringComparison.OrdinalIgnoreCase));prefs.RecentProjects.Insert(0,project.ManifestPath);if(prefs.RecentProjects.Count>12)prefs.RecentProjects.RemoveRange(12,prefs.RecentProjects.Count-12);prefs.Persist();RefreshRecents();}
 void RefreshRecents(){loading=true;recent.Items.Clear();foreach(var path in DossierPreferences.Current.RecentProjects)recent.Items.Add(new RecentProject{Path=path});recent.SelectedIndex=-1;loading=false;}
 void Render(){name.Enabled=description.Enabled=project!=null;name.Text=project?.Name??"";description.Text=project?.Description??"";location.Text=project?.Root??"Create a project or open dossier-project.json to begin.";Text="MPN Dossier REVANCED — Project Manager"+(project==null?"":" / "+project.Name);RefreshFolders();}
 void RefreshFolders(){var selected=Folder?.Path;folders.DataSource=project?.Folders.ToArray()??new DossierProjectFolder[0];if(selected!=null)folders.SelectedItem=project?.Folders.FirstOrDefault(f=>f.Path==selected);RefreshFiles();}
 void RefreshFiles(){var issues=new List<string>();var selected=FileEntry?.Path;allFiles=project?.Scan(issues)??new List<DossierProjectFile>();loading=true;var previous=(scope.SelectedItem as FolderScope)?.Folder?.Path;scope.Items.Clear();scope.Items.Add(new FolderScope());if(project!=null)foreach(var f in project.Folders)scope.Items.Add(new FolderScope{Folder=f});scope.SelectedItem=scope.Items.Cast<FolderScope>().FirstOrDefault(f=>f.Folder?.Path==previous)??scope.Items[0];loading=false;FilterFiles(selected);summary.Text=project==null?"Characters, rooms, assets, notes and ideas — together.":allFiles.Count+" files in "+project.Folders.Count+" folders.\r\n"+project.Folders.Count(f=>!Directory.Exists(project.Resolve(f)))+" missing folder links.";status.Text=issues.Count==0?allFiles.Count+" files · double-click a JSON entry to edit it.":string.Join(" · ",issues.Take(3));}
 void FilterFiles()=>FilterFiles(FileEntry?.Path);
 void FilterFiles(string keep){if(loading)return;var selected=(scope.SelectedItem as FolderScope)?.Folder;var words=search.Text.Split(new[]{' '},StringSplitOptions.RemoveEmptyEntries);var visible=allFiles.Where(f=>(selected==null||ReferenceEquals(f.Folder,selected))&&words.All(w=>(f.ToString()+" "+f.Path).IndexOf(w,StringComparison.OrdinalIgnoreCase)>=0)).OrderBy(f=>f.ToString(),StringComparer.OrdinalIgnoreCase).ToArray();files.DataSource=visible;if(keep!=null)files.SelectedItem=visible.FirstOrDefault(f=>f.Path==keep);ReadPreview();}
 void SaveDetails(){RequireProject();project.Commit(()=>{project.Name=name.Text.Trim();project.Description=description.Text;});Render();status.Text="Project details saved. Entry editors save their own JSON files.";}
 void LinkFolder(){RequireProject();using(var dialog=new DossierFolderBrowserDialog{Description="Link an existing folder. Its files will stay in place."})if(dialog.ShowDialog(this)==DialogResult.OK){project.Commit(()=>project.LinkFolder(dialog.SelectedPath,kind.SelectedItem.ToString()));RefreshFolders();}}
 void SetKind(){RequireProject();var folder=Folder;if(folder==null)return;project.Commit(()=>folder.Kind=kind.SelectedItem.ToString());RefreshFolders();}
 void UnlinkFolder(){RequireProject();var folder=Folder;if(folder==null)return;project.Commit(()=>project.Folders.Remove(folder));RefreshFolders();status.Text="Folder unlinked. Its files are still on disk.";}
 DossierProjectFolder TargetFolder()=>tabs.SelectedIndex==1?(scope.SelectedItem as FolderScope)?.Folder??FileEntry?.Folder:Folder;
 void ImportFiles(){RequireProject();var target=TargetFolder();if(target==null)throw new InvalidOperationException("Choose a folder in Overview or the Show folder filter first.");using(var dialog=new DossierOpenFileDialog{Title="Copy files into "+target.Kind+" (originals stay in place)",Filter="All files (*.*)|*.*",Multiselect=true})if(dialog.ShowDialog(this)==DialogResult.OK){var imported=project.ImportFiles(target,dialog.FileNames);RefreshFiles();status.Text="Copied "+imported.Count+" files. Existing filenames were kept; copies get a numbered name.";}}
 void LinkDeck(){RequireProject();var decks=DossierDecks.Load();if(decks.Decks.Count==0)throw new InvalidOperationException("No saved decks yet. Open decks to create one, or Link folder directly.");using(var picker=new ProjectDeckPicker(decks.Decks))if(picker.ShowDialog(this)==DialogResult.OK){int count=0;project.Commit(()=>count=project.LinkDeck(picker.Selected));RefreshFolders();status.Text="Linked "+count+" deck folders. Files stayed in place.";}}
 void ReadPreview(){var file=FileEntry;if(file==null){preview.Text="Select a file to preview it. Choose a typed folder to create a new entry there.";return;}try{var info=new FileInfo(file.Path);string ext=Path.GetExtension(file.Path).ToLowerInvariant();if(info.Length<=2*1024*1024&&ext==".json")preview.Text=file.Path+"\r\n\r\n"+JToken.Parse(File.ReadAllText(file.Path));else if(info.Length<=128*1024&&new[]{".txt",".md",".log",".xml"}.Contains(ext))preview.Text=file.Path+"\r\n\r\n"+File.ReadAllText(file.Path);else preview.Text=file.Path+"\r\n\r\n"+info.Length.ToString("N0")+" bytes\r\nAsset in this project. Use Show in folder to access it.";}catch(Exception ex){preview.Text="Could not preview: "+ex.Message;}}
 void OpenEntry(bool create){RequireProject();var file=FileEntry;var folder=create?TargetFolder():file?.Folder;if(folder==null||!DossierDecks.EntryKinds.ContainsKey(folder.Kind))throw new InvalidOperationException("Choose a typed entry folder, such as characters, weapons or rooms. Set its type in Overview.");string directory=project.Resolve(folder);if(!Directory.Exists(directory))throw new DirectoryNotFoundException("This folder is missing. Relink it in Overview.");if(!create&&(file==null||!file.Path.EndsWith(".json",StringComparison.OrdinalIgnoreCase)||new FileInfo(file.Path).Length>2*1024*1024))throw new InvalidOperationException("Select a JSON entry smaller than 2 MB.");
  if(create&&folder.Kind=="characters"){DossierCharacterCreator.Open(this,directory);return;}
  if(folder.Kind=="rooms"){var room=new DossierRoomEditor(false);try{room.SetRoomFolder(directory);if(!create)room.OpenPath(file.Path);StudioModule.ShowDocument(room,this);}catch{room.Dispose();throw;}}
  else{var editor=new FormEditorV2();try{editor.OpenDeckEntry(folder.Kind,create?null:file.Path,create?directory:Path.GetDirectoryName(file.Path));StudioModule.ShowDocument(editor,this);}catch{editor.Dispose();throw;}}
 }
 void OpenIdeas(){RequireProject();DossierIdeaGallery.Open(this,project.IdeasPath,project.Name);}
 void Reveal(bool selected){RequireProject();string path=selected&&FileEntry!=null?FileEntry.Path:project.Root;if(!File.Exists(path)&&!Directory.Exists(path))throw new IOException("This location is missing.");DossierExplorer.Open(this,path);}
 sealed class RecentProject{public string Path;public override string ToString()=>Path+(File.Exists(Path)?"":" (missing)");}
 sealed class FolderScope{public DossierProjectFolder Folder;public override string ToString()=>Folder?.ToString()??"All project folders";}
 sealed class ProjectDeckPicker:Form
 {
  public DossierDeck Selected{get;private set;}
  public ProjectDeckPicker(List<DossierDeck> decks){DossierDpi.Initialize(this);Text="Link folders from a deck";Size=new Size(580,400);StartPosition=FormStartPosition.CenterParent;var list=new ListBox{Dock=DockStyle.Fill,DataSource=decks};var button=new DossierButton{Text="Link selected deck",Dock=DockStyle.Bottom,Height=40};button.Click+=(_,__)=>{Selected=list.SelectedItem as DossierDeck;if(Selected!=null)DialogResult=DialogResult.OK;};Controls.Add(list);Controls.Add(button);DossierStyle.Apply(this);DossierDpi.Complete(this);}
 }
